import java.util.Map;

public class Solution {
    private static final Map<Character, String> MORSE_MAP = Map.ofEntries(
        Map.entry('A', ".-"),
        Map.entry('B', "-..."),
        Map.entry('C', "-.-."),
        Map.entry('D', "-.."),
        Map.entry('E', "."),
        Map.entry('F', "..-."),
        Map.entry('G', "--."),
        Map.entry('H', "...."),
        Map.entry('I', ".."),
        Map.entry('J', ".---"),
        Map.entry('K', "-.-"),
        Map.entry('L', ".-.."),
        Map.entry('M', "--"),
        Map.entry('N', "-."),
        Map.entry('O', "---"),
        Map.entry('P', ".--."),
        Map.entry('Q', "--.-"),
        Map.entry('R', ".-."),
        Map.entry('S', "..."),
        Map.entry('T', "-"),
        Map.entry('U', "..-"),
        Map.entry('V', "...-"),
        Map.entry('W', ".--"),
        Map.entry('X', "-..-"),
        Map.entry('Y', "-.--"),
        Map.entry('Z', "--..")
    );

    public static String morseChar(String c) {
        if (c == null || c.isEmpty()) {
            return "?";
        }
        char ch = c.charAt(0);
        return switch (ch) {
            case 'A' -> ".-";
            case 'B' -> "-...";
            case 'C' -> "-.-.";
            case 'D' -> "-..";
            case 'E' -> ".";
            case 'F' -> "..-.";
            case 'G' -> "--.";
            case 'H' -> "....";
            case 'I' -> "..";
            case 'J' -> ".---";
            case 'K' -> "-.-";
            case 'L' -> ".-..";
            case 'M' -> "--";
            case 'N' -> "-.";
            case 'O' -> "---";
            case 'P' -> ".--.";
            case 'Q' -> "--.-";
            case 'R' -> ".-.";
            case 'S' -> "...";
            case 'T' -> "-";
            case 'U' -> "..-";
            case 'V' -> "...-";
            case 'W' -> ".--";
            case 'X' -> "-..-";
            case 'Y' -> "-.--";
            case 'Z' -> "--..";
            default -> "?";
        };
    }

    public static void main(String[] args) {
        System.out.println(morseChar("A"));
        System.out.println(morseChar("S"));
        System.out.println(morseChar("Z"));
        System.out.println(morseChar("?"));
        System.out.println(morseChar(""));
        System.out.println(morseChar("a"));
        System.out.println(morseChar("1"));
        System.out.println(morseChar("HELLO".substring(0, 1)));
    }
}
